  // Synchronize dst_ack to src domain
  always @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni)
      dst_ack_sync <= 2'b00;
    else
      dst_ack_sync <= {dst_ack_sync[0], dst_ack_r};
