  // Source domain logic
  assign src_ready_o = !src_pending_r;

  always @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
      src_req_r <= 1'b0;
      src_data_hold_r <= {WIDTH{1'b0}};
      src_pending_r <= 1'b0;
    end else begin
      if (src_req_r && dst_ack_sync[1]) begin
        src_req_r <= 1'b0;
        src_pending_r <= 1'b0;
